<?php require_once __DIR__.'/lib/inicio.php';exigir_sesion();if(!es_control())ir('panel.php');if($_SERVER['REQUEST_METHOD']==='POST'){try{validar_token();$hash=password_hash($_POST['nueva_clave'],PASSWORD_DEFAULT);$id=(int)$_POST['id_usuario'];$s=bd()->prepare('UPDATE usuarios SET clave_hash=?,debe_cambiar_clave=1 WHERE id_usuario=?');$s->bind_param('si',$hash,$id);$s->execute();mensaje('Contraseña actualizada.');ir('usuarios.php');}catch(Throwable $e){mensaje($e->getMessage(),'error');ir('usuarios.php');}}$lista=bd()->query('SELECT u.*,d.numero_distrito FROM usuarios u LEFT JOIN distritos d ON d.id_distrito=u.id_distrito ORDER BY u.id_usuario')->fetch_all(MYSQLI_ASSOC);include 'encabezado.php';?><section class="tarjeta"><h1>Usuarios del sistema</h1><table><tr><th>Usuario</th><th>Nombre</th><th>Perfil</th><th>Distrito</th><th>Nueva contraseña</th></tr><?php foreach($lista as $u):?><tr><td><?=h($u['nombre_usuario'])?></td><td><?=h($u['nombre_completo'])?></td><td><?=h($u['perfil'])?></td><td><?=h((string)$u['numero_distrito'])?></td><td><form method="post"><input type="hidden" name="token" value="<?=token()?>"><input type="hidden" name="id_usuario" value="<?=$u['id_usuario']?>"><input name="nueva_clave" minlength="10" required><button class="boton">Cambiar</button></form></td></tr><?php endforeach?></table></section><?php include 'pie.php';?>